import json, collections
from common import ROOT
d = json.load(open(ROOT / 'data' / 'events.json')); ev = sorted(d['events'], key=lambda e: e['t']); K = d['K']; mix = json.load(open(ROOT / 'audio' / 'mix_log.json'))
BEAT = .5
def bb(t): b = t / BEAT; return f'{int(b // 4) + 1} : {b % 4 + 1:g}'
# drum timetable
names = {'kick': 'kick', 'snare': 'snare', 'hat': 'hat', 'hat_open': 'open hat', 'crash': 'crash', 'crash_lift': 'crash', 'crash_off': 'crash', 'kick_lift': 'kick', 'kick_roof': 'kick', 'roll': 'tom roll', 'fill': 'tom fill'}
rows = collections.defaultdict(list)
for t, s, n in sorted(mix):
    if s in ('kick', 'drums') and n in names: rows[names[n]].append(t)
out = ['| drum | hits | times (s) |', '|---|---|---|']
for k in ('kick', 'snare', 'hat', 'open hat', 'crash', 'tom roll', 'tom fill'):
    ts = sorted(set(round(x, 3) for x in rows[k]))
    out.append(f'| {k} | {len(ts)} | ' + ', '.join(f'{x:g}' for x in ts) + ' |')
drums = '\n'.join(out)
# beat → animation (milestones; typed lines + furniture condensed)
by = collections.OrderedDict()
for e in ev: by.setdefault(e['name'], []).append(e['t'])
g = sorted(by.items(), key=lambda kv: kv[1][0])
desc = {'intro': 'editor appears, caret starts', 'type': 'a source line lands (its last character on this beat)', 'grid': 'plan grid draws in; glockenspiel triad', 'north': 'north arrow', 'wall': 'plan wall strokes grow (one per hit)', 'room': 'room fills + labels', 'door': 'door arcs open (finger snaps)', 'window': 'window glazing lines (ride bell)', 'furn2d': 'furniture symbols pop in (vibraphone)', 'title': 'title block fades in on the plan (start of the breath before the lift)', 'result': 'compile result read-out (diagnostics, rooms, area) springs in under the code', 'dims': 'dimension strings run in along the plan (led by a reversed-crash swell)', 'still': 'marker for the held beat before the lift', 'lift': 'plan → 3D: crash + kick, floor slab springs up, plan fades as the walls grow', 'rise': 'wall rises from the plan line (tom)', 'furn3d': '3D furniture drops in (vibraphone/claves)', 'door_open': 'front / bedroom door swings (open-hat chik)', 'slide': 'camera slides through the house', 'whoosh_up': 'camera lifts out; reversed-crash whoosh', 'roof_start': 'roof starts to descend', 'roof_land': 'roof lands: kick + tom + claves, aerial hold', 'roof_off': 'roof off; crash', 'collapse': 'walls fold back down to the plan (toms)', 'logo': 'logo mark draws; glockenspiel high C', 'letters': 'word-mark letters (vibraphone arpeggio)', 'slogan': 'slogan words, one per beat-subdivision', 'sub': 'sub-line', 'chips': 'format / npx / GitHub / MIT chips'}
out = ['| bar : beat | time (s) | event | what moves / what you hear |', '|---|---|---|---|']
for key, ts in g:
    lab = key if len(ts) == 1 else f'{key} ×{len(ts)}'
    span = f'{ts[0]:g}' if len(ts) == 1 else f'{ts[0]:g} … {ts[-1]:g}'
    out.append(f'| {bb(ts[0])} | {span} | {lab} | {desc.get(key, "")} |')
beat = '\n'.join(out)
docs = ROOT / 'docs'
(docs / 'drum_timetable.md').write_text('# Drum timetable (120 BPM, 4/4, 1 beat = 0.5 s)\n\nGenerated by `scripts/mkreadme_tables.py` from `audio/mix_log.json` (the exact hits the score places).\n\n' + drums + '\n')
(docs / 'beat_to_animation.md').write_text('# Beat → animation events\n\nGenerated by `scripts/mkreadme_tables.py` from `data/events.json` (the html\'s own event list; the score reads the same file).\n`bar : beat` counts bars of 4 beats from 1 : 1 at t = 0; `…` marks the first and last of a run.\n\n' + beat + '\n')
print('wrote', docs / 'drum_timetable.md', 'and', docs / 'beat_to_animation.md')
